/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    next init();

    //if(salesEditLinesForm is SalesEditLinesForm_PackingSlip)
   // {
    //    salesEditLinesForm.parmAVADlvModeIdParmeterVisible(true);
    //}

    if(salesEditLinesForm is SalesEditLinesForm_Invoice)
    {
        SalesParmUpdate_AVAEDITransfer.visible(true);
        if(salesFormLetter.parmCallerFormName() == '')
        {
            this.design().controlName(formControlStr(SalesEditLines,AVABatchProcessing_AVAInvoiceBackdatingDays)).visible(true);
            this.design().controlName(formControlStr(SalesEditLines,AVABatchProcessing_AVAShiftDays)).visible(true);
        }
    }
    else
    {
        SalesParmUpdate_AVAEDITransfer.visible(false);
    }

    SalesParmUpdate_AVADlvModeId.visible(salesEditLinesForm.parmAVADlvModeIdParmeterVisible());
}

