/// <summary>
/// N.Freidenberger 26.04.24
/// </summary>
void  specQtyChanged()
{
   if (salesParmUpdate.SumBy != AccountOrder::Journal && salesParmUpdate.SpecQty == SalesUpdate::PackingSlip)
    {
        salesParmUpdate.SumBy = AccountOrder::Journal;
        sumBy.selection(salesEditLinesForm.sumByIndex2Selection(AccountOrder::Journal));
     //   salesFormLetter.reArrange(false);

    }         
    if (salesParmUpdate.SumBy == AccountOrder::Journal && (salesParmUpdate.SpecQty == SalesUpdate::All || SalesParmUpdate.SpecQty == SalesUpdate::DeliverNow))
    {
        salesParmUpdate.SumBy = AccountOrder::None;
        sumBy.selection(salesEditLinesForm.sumByIndex2Selection(AccountOrder::None));
        //   salesFormLetter.reArrange(false);

    }
    next    specQtyChanged();

/*          */
}

void updateQueryFromShiftDays()
{
    TransDate   lastPackingSlipDate;
    salesFormLetter.initParameters(salesParmUpdate.data(),
                                    print_Combo.selection(),
                                    printFormletter.value(),
                                    printCODLabelChoice,
                                    printShippingLabelChoice,
                                    usePrintManagement.value(),
                                    true,
                                    #PdsMRCEnabled ? pdsMRCPostingError.value(): NoYes::No,
                                    #PdsMRCEnabled ? pdsMRCPrintOnPack.value(): NoYes::No,
                                    fiscalDocType_PL.selection(),
                                    printexciseformletter.value()
                                    );

    salesFormLetter.editLinesChanged(editLinesChanged);
    salesFormLetter.reArrangeNow(reArrangeNow);
    salesFormLetter.initLinesQuery();
    Query   query = salesFormLetter.parmQueryUsed();
    if(salesParmUpdate.AVAShiftDays != -1)
    {
        lastPackingSlipDate = systemDateGet() - salesParmUpdate.AVAShiftDays;

        QueryBuildDataSource        salesTableDS = query.dataSourceTable(tableNum(SalesTable));
        if(salesTableDS)
        {
            QueryBuildDataSource        salesPackingSlipLinkDS = salesTableDS.addDataSource(tableNum(custPackingSlipSalesLink));
            salesPackingSlipLinkDS.joinMode(JoinMode::InnerJoin);
            salesPackingSlipLinkDS.addLink(fieldnum(SalesTable,SalesId),fieldNum(CustPackingSlipSalesLink,OrigSalesId));

            SysQuery::findOrCreateRange(salesPackingSlipLinkDS,fieldnum(custPackingSlipSalesLink,DeliveryDate)).value(SysQuery::range(datenull(),lastPackingSlipDate));
        }

        if (salesParmUpdate.LateSelection)
        {
            salesParmUpdate.LateSelectionQuery = query.pack();

            this.initQuery();
        }
        else
        {

            salesParmUpdate.LateSelection = false;
        }

        this.chooseTable(true);
    }
}
